// =====================================================================
// Pioneer VFD v0.3.2 — DEH-P7600MP Spicetify extension
//   All animations strictly INSIDE the LCD window.
//   v0.3.2: tighter contained RACING viewport with larger VFD frame gutters.
// =====================================================================

(function PioneerVFD() {
  if (!window.Spicetify || !Spicetify.Player || !Spicetify.CosmosAsync) {
    setTimeout(PioneerVFD, 300);
    return;
  }

  const NUM_BARS = 48;
  const SMOOTHING = 0.72;
  const FRAME_INTERVAL_MS = 33;
  const TIMBRE_SCALE = 0.012;
  const PEAK_HOLD_MS = 600;
  const MODE_CYCLE_MS = 10000;
  const SINE_BASE = 0.30;
  const MODES = ["DOLPHIN", "GALAXY", "SPECTRUM", "DEMO", "CLIP"];
  const SCRUB_MS_PER_TICK = 5000;
  // LCD clip frame constants. Panel res matches the DEH-P7600MP logical cell grid.
  const PANEL_W = 96, PANEL_H = 18;
  const DITHER_LEVELS = 16;
  // 8x8 Bayer threshold matrix, normalized to [-0.5, 0.5).
  const BAYER8 = new Float32Array([
    0,32, 8,40, 2,34,10,42,
   48,16,56,24,50,18,58,26,
   12,44, 4,36,14,46, 6,38,
   60,28,52,20,62,30,54,22,
    3,35,11,43, 1,33, 9,41,
   51,19,59,27,49,17,57,25,
   15,47, 7,39,13,45, 5,37,
   63,31,55,23,61,29,53,21,
  ]).map(v => v / 64 - 0.5);

  // TINT cycle: hue-rotate degrees applied to the LCD as a CSS filter.
  // Native LCD output is cyan-dominant (hue ~180°). To land on amber (~45°)
  // and violet (~280°): rotation = (target - 180) mod 360.
  const TINT_LABELS = ["CYAN", "AMBER", "VIOLET"];
  const TINT_HUE_DEG = [0, 225, 100];
  let tintIdx = 0;

  // CLIP mode: pre-dithered/packed LCD frame clips. This avoids Spotify/Electron
  // blocking embedded MP4 blob playback and makes the LCD videos deterministic.
  const CLIPS = [{"name":"DOLPHIN","fps":12,"w":96,"h":18,"frames":82,"data":""},{"name":"RACING","fps":12,"w":96,"h":18,"frames":96,"data":""}];
  let clipIdx = 0;
  let clipStartMs = 0;


  let analysis = null, segments = [], beats = [], beatIdx = 0;
  let barHeights = new Array(NUM_BARS).fill(0);
  let peakHeights = new Array(NUM_BARS).fill(0);
  let peakTimestamps = new Array(NUM_BARS).fill(0);
  let lastSegmentIdx = 0;

  let canvas = null, ctx = null;
  let modeIdx = 0;
  let modeLastSwitchMs = 0;
  let modeForcedIdx = -1;
  let lcdDimmed = false;
  let chassis = null;
  let trackTitle = "", trackArtist = "";
  let lastTrackUri = "";

  let dolphinX = -50;
  const dolphinBubbles = [];
  let demoSweep = 0;

  function fmtTime(ms) {
    const s = Math.max(0, Math.floor((ms || 0) / 1000));
    return `${Math.floor(s/60)}:${String(s%60).padStart(2,"0")}`;
  }

  function findPlayerBar() {
    const root = document.querySelector(".Root__now-playing-bar");
    if (root) return root;

    const testIdBar = document.querySelector("[data-testid='now-playing-bar']");
    if (testIdBar) {
      const rootParent = testIdBar.closest(".Root__now-playing-bar");
      return rootParent || testIdBar;
    }

    return document.querySelector(".main-nowPlayingBar-container");
  }

  function preparePlayerBar(bar) {
    if (!bar) return;
    document.documentElement.classList.add("pvfd-theme-active");
    document.body.classList.add("pvfd-theme-active");
    bar.classList.add("pvfd-mounted");
    bar.style.setProperty("height", "var(--pvfd-player-height)", "important");
    bar.style.setProperty("min-height", "var(--pvfd-player-height)", "important");
    bar.style.setProperty("max-height", "var(--pvfd-player-height)", "important");
    bar.style.setProperty("position", "relative", "important");
    bar.style.setProperty("overflow", "hidden", "important");
  }

  function hideNativePlayerChildren(bar) {
    if (!bar) return;
    Array.from(bar.children).forEach((child) => {
      if (!child.classList || !child.classList.contains("pvfd-chassis")) {
        child.classList.add("pvfd-native-player-hidden");
        child.setAttribute("aria-hidden", "true");
      }
    });
  }

  function buildChassis() {
    const root = document.createElement("div");
    root.className = "pvfd-chassis";
    root.innerHTML = `
      <div class="pvfd-faceplate">
        <div style="display:flex;align-items:center;gap:14px;justify-content:flex-start;">
          <span class="pvfd-silk-eeq">EEQ</span>
          <span class="pvfd-silk-label">MOSFET 50W&times;4</span>
        </div>
        <span class="pvfd-silk-pioneer">Pioneer</span>
        <div style="display:flex;align-items:center;gap:12px;justify-content:flex-end;">
          <span class="pvfd-silk-label">WMA / MP3</span>
          <span class="pvfd-silk-dab">DAB CONTROL</span>
          <div style="display:flex;align-items:center;gap:4px;">
            <span style="color:#d8dce0;font-size:10px;font-weight:700;letter-spacing:0.5px;">OPEN</span>
            <div class="pvfd-open-led" data-pvfd="open" title="Open device picker"></div>
          </div>
        </div>
      </div>

      <div class="pvfd-mainrow">
        <div class="pvfd-knob-wrap">
          <div class="pvfd-knob" data-pvfd="lknob" title="Volume (scroll or drag)">
            <div class="pvfd-knob-glow"></div>
            <div class="pvfd-knob-bezel"></div>
            <div class="pvfd-knob-led-arc"></div>
            <div class="pvfd-knob-cap"></div>
            <div class="pvfd-knob-indicator"></div>
          </div>
        </div>

        <div class="pvfd-flank">
          <div class="pvfd-pill" data-pvfd="scan" title="Cycle LCD mode">SCAN</div>
          <div class="pvfd-pill" data-pvfd="dim"  title="Toggle LCD brightness">DIM</div>
          <div class="pvfd-pill" data-pvfd="clip" title="Play dithered video clip (re-click to switch clip)">CLIP</div>
        </div>

        <div class="pvfd-lcd">
          <canvas class="pvfd-lcd-canvas"></canvas>
          <div class="pvfd-lcd-pixelgrid"></div>
          <div class="pvfd-lcd-phosphor"></div>
          <div class="pvfd-lcd-track"></div>
          <div class="pvfd-lcd-artist"></div>
          <div class="pvfd-lcd-time">0:00</div>
          <div class="pvfd-lcd-info-l">
            <span class="pvfd-lcd-deh">DEH-P7600MP</span>
            <span class="pvfd-lcd-daq">DAQ</span>
          </div>
          <div class="pvfd-lcd-info-r">
            <span class="pvfd-lcd-cdrds">CD-RDS</span>
            <span class="pvfd-lcd-pioneer-small">Pioneer</span>
          </div>
        </div>

        <div class="pvfd-flank">
          <div class="pvfd-pill" data-pvfd="demo" title="Lock LCD to the current animation">DEMO</div>
          <div class="pvfd-pill" data-pvfd="menu" title="More options">MENU</div>
          <div class="pvfd-pill" data-pvfd="tint" title="Cycle LCD color (cyan / amber / violet)">TINT</div>
        </div>

        <div class="pvfd-knob-wrap">
          <div class="pvfd-nav" title="Outer ring scrolls to scrub. Center = play/pause. Arrows = save/queue/prev/next">
            <div class="pvfd-nav-glow"></div>
            <div class="pvfd-nav-outer" data-pvfd="navring"></div>
            <div class="pvfd-nav-led-ring"></div>
            <div class="pvfd-nav-inner-ring"></div>
            <div class="pvfd-nav-button" data-pvfd="navcenter"></div>
            <div class="pvfd-nav-arrow up"    data-pvfd="navup"    title="Save/like">&#9650;</div>
            <div class="pvfd-nav-arrow down"  data-pvfd="navdn"    title="Add to queue">&#9660;</div>
            <div class="pvfd-nav-arrow left"  data-pvfd="navleft"  title="Previous">&#9664;</div>
            <div class="pvfd-nav-arrow right" data-pvfd="navright" title="Next">&#9654;</div>
          </div>
        </div>
      </div>

      <div class="pvfd-transport">
        <div class="pvfd-tab-side" data-pvfd="queue" title="Queue">QUE<div class="pvfd-led-strip"></div></div>
        <div class="pvfd-preset-row">
          <div class="pvfd-tab-preset" data-pvfd="shuffle" title="Shuffle">&#8646;<div class="pvfd-led-strip"></div></div>
          <div class="pvfd-tab-preset" data-pvfd="prev"    title="Previous">&#9198;<div class="pvfd-led-strip"></div></div>
          <div class="pvfd-tab-preset" data-pvfd="play"    title="Play / pause">&#9654;<div class="pvfd-led-strip"></div></div>
          <div class="pvfd-tab-preset" data-pvfd="next"    title="Next">&#9197;<div class="pvfd-led-strip"></div></div>
          <div class="pvfd-tab-preset" data-pvfd="repeat"  title="Repeat">&#8635;<div class="pvfd-led-strip"></div></div>
          <div class="pvfd-tab-preset" data-pvfd="love"    title="Save to liked">&#9829;<div class="pvfd-led-strip"></div></div>
        </div>
        <div class="pvfd-tab-side" data-pvfd="devices" title="Devices">DEV<div class="pvfd-led-strip"></div></div>
      </div>
    `;
    return root;
  }

  function injectChassis() {
    const bar = findPlayerBar();
    if (!bar) return false;

    preparePlayerBar(bar);

    if (bar.querySelector(".pvfd-chassis")) {
      chassis = bar.querySelector(".pvfd-chassis");
      hideNativePlayerChildren(bar);
      canvas = chassis.querySelector(".pvfd-lcd-canvas");
      if (canvas) ctx = canvas.getContext("2d");
      sizeCanvas();
      return true;
    }

    hideNativePlayerChildren(bar);
    chassis = buildChassis();
    bar.appendChild(chassis);
    hideNativePlayerChildren(bar);

    canvas = chassis.querySelector(".pvfd-lcd-canvas");
    if (canvas) {
      ctx = canvas.getContext("2d");
      sizeCanvas();
      window.addEventListener("resize", sizeCanvas);
    }
    wireControls();
    return true;
  }

  function sizeCanvas() {
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const dpr = Math.max(1, Math.min(2, window.devicePixelRatio || 1));
    canvas.width  = Math.floor(rect.width  * dpr);
    canvas.height = Math.floor(rect.height * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }

  function bind(el, fn) { if (el) el.addEventListener("click", fn); }
  function safe(fn) { try { fn(); } catch (e) { console.warn("[PVFD]", e); } }

  function wireControls() {
    const $ = (sel) => chassis.querySelector(sel);

    const lknob = $("[data-pvfd='lknob']");
    if (lknob) {
      lknob.addEventListener("wheel", (e) => {
        e.preventDefault();
        const cur = Spicetify.Player.getVolume();
        Spicetify.Player.setVolume(Math.max(0, Math.min(1, cur - e.deltaY * 0.0008)));
      }, { passive: false });
      let dragging = false, lastY = 0;
      lknob.addEventListener("mousedown", (e) => { dragging = true; lastY = e.clientY; e.preventDefault(); });
      window.addEventListener("mousemove", (e) => {
        if (!dragging) return;
        const dy = lastY - e.clientY; lastY = e.clientY;
        const cur = Spicetify.Player.getVolume();
        Spicetify.Player.setVolume(Math.max(0, Math.min(1, cur + dy * 0.005)));
      });
      window.addEventListener("mouseup", () => { dragging = false; });
    }

    const navring = $("[data-pvfd='navring']");
    if (navring) {
      navring.addEventListener("wheel", (e) => {
        e.preventDefault();
        const dir = e.deltaY > 0 ? -1 : 1;
        const cur = Spicetify.Player.getProgress();
        Spicetify.Player.seek(Math.max(0, cur + dir * SCRUB_MS_PER_TICK));
      }, { passive: false });
    }

    bind($("[data-pvfd='navcenter']"), () => Spicetify.Player.togglePlay());
    bind($("[data-pvfd='navup']"),    () => safe(() => Spicetify.Player.toggleHeart()));
    bind($("[data-pvfd='navdn']"),    () => safe(() => {
      if (Spicetify.addToQueue && Spicetify.Player.data && Spicetify.Player.data.item) {
        Spicetify.addToQueue([Spicetify.Player.data.item.uri]);
      }
    }));
    bind($("[data-pvfd='navleft']"),  () => Spicetify.Player.back());
    bind($("[data-pvfd='navright']"), () => Spicetify.Player.next());

    bind($("[data-pvfd='scan']"), () => {
      const wasLocked = modeForcedIdx >= 0;
      modeIdx = (modeIdx + 1) % MODES.length;
      modeLastSwitchMs = performance.now();
      if (wasLocked) modeForcedIdx = modeIdx;
    });
    bind($("[data-pvfd='dim']"), () => {
      lcdDimmed = !lcdDimmed;
      applyLcdFilter();
      $("[data-pvfd='dim']").classList.toggle("active", lcdDimmed);
    });
    bind($("[data-pvfd='clip']"), () => {
      const idx = MODES.indexOf("CLIP");
      if (idx < 0) return;
      if (modeIdx === idx) setActiveClip(clipIdx + 1);
      else setActiveClip(clipIdx);
      modeIdx = idx;
      modeLastSwitchMs = performance.now();
      if (modeForcedIdx >= 0) modeForcedIdx = idx;
      const clipBtn = $("[data-pvfd='clip']");
      if (clipBtn) {
        clipBtn.classList.add("active");
        setTimeout(() => clipBtn.classList.remove("active"), 900);
      }
    });
    bind($("[data-pvfd='tint']"), () => {
      tintIdx = (tintIdx + 1) % TINT_HUE_DEG.length;
      applyLcdFilter();
      const tintBtn = $("[data-pvfd='tint']");
      if (tintBtn) {
        tintBtn.textContent = TINT_LABELS[tintIdx];
        tintBtn.classList.toggle("active", tintIdx !== 0);
      }
    });
    bind($("[data-pvfd='demo']"), () => {
      const demoBtn = $("[data-pvfd='demo']");
      if (modeForcedIdx >= 0) {
        modeForcedIdx = -1;
        if (demoBtn) demoBtn.classList.remove("active");
      } else {
        modeForcedIdx = modeIdx;
        modeLastSwitchMs = performance.now();
        if (demoBtn) demoBtn.classList.add("active");
      }
    });
    bind($("[data-pvfd='menu']"), () => {
      const tgt = document.querySelector("[data-testid='now-playing-widget']") || document.body;
      tgt.dispatchEvent(new MouseEvent("contextmenu", { bubbles: true, cancelable: true, view: window }));
    });
    bind($("[data-pvfd='open']"), () => {
      const btn = document.querySelector("[data-testid='control-button-connect-picker'], button[aria-label*='evices']");
      if (btn) btn.click();
    });

    bind($("[data-pvfd='shuffle']"), () => safe(() => Spicetify.Player.toggleShuffle()));
    bind($("[data-pvfd='prev']"),    () => Spicetify.Player.back());
    bind($("[data-pvfd='play']"),    () => Spicetify.Player.togglePlay());
    bind($("[data-pvfd='next']"),    () => Spicetify.Player.next());
    bind($("[data-pvfd='repeat']"),  () => safe(() => Spicetify.Player.toggleRepeat()));
    bind($("[data-pvfd='love']"),    () => safe(() => Spicetify.Player.toggleHeart()));
    bind($("[data-pvfd='queue']"),   () => {
      const q = document.querySelector("[data-testid='control-button-queue']");
      if (q) q.click();
    });
    bind($("[data-pvfd='devices']"), () => {
      const d = document.querySelector("[data-testid='control-button-connect-picker']");
      if (d) d.click();
    });
  }

  async function loadAnalysis(uri) {
    if (!uri) return;
    const id = uri.split(":").pop();
    try {
      const data = await Spicetify.CosmosAsync.get(`https://api.spotify.com/v1/audio-analysis/${id}`);
      analysis = data;
      segments = (data && data.segments) || [];
      beats    = (data && data.beats)    || [];
      beatIdx = 0; lastSegmentIdx = 0;
      console.log("[PVFD] analysis:", segments.length, "segments,", beats.length, "beats");
    } catch (err) {
      console.warn("[PVFD] audio-analysis fetch failed:", err);
      analysis = null; segments = []; beats = [];
    }
  }

  function findCurrentSegment(tSec) {
    if (!segments.length) return null;
    let i = lastSegmentIdx;
    while (i < segments.length && segments[i].start + segments[i].duration < tSec) i++;
    while (i > 0 && segments[i].start > tSec) i--;
    lastSegmentIdx = Math.max(0, Math.min(segments.length - 1, i));
    return segments[lastSegmentIdx];
  }

  function beatPulse(tSec) {
    if (!beats.length) return 0;
    while (beatIdx < beats.length && beats[beatIdx].start < tSec - 0.05) beatIdx++;
    if (beatIdx === 0) return 0;
    const last = beats[beatIdx - 1];
    return Math.exp(-(tSec - last.start) * 5);
  }

  function updateBars() {
    const tSec = (Spicetify.Player.getProgress() || 0) / 1000;
    const seg = findCurrentSegment(tSec);
    const isPlaying = Spicetify.Player.isPlaying();
    const wall = performance.now() / 1000;

    // Spotify audio-analysis can fail or return sparse data. Do NOT let the LCD go black.
    // Use a period-correct fake analyzer fallback so every demo mode stays alive.
    for (let i = 0; i < NUM_BARS; i++) {
      let target;
      if (seg && isPlaying) {
        const t = seg.timbre || [];
        const tIdx = Math.floor((i / NUM_BARS) * 12);
        const raw = Math.abs(t[tIdx] || 0) * TIMBRE_SCALE;
        const ripple = 0.10 * Math.sin(wall * 3.2 + i * 0.45) + 0.08 * Math.sin(wall * 6.0 + i * 0.17);
        target = Math.max(0.10, Math.min(1, raw + ripple));
      } else if (isPlaying) {
        target = 0.20
          + 0.34 * Math.abs(Math.sin(wall * 1.55 + i * 0.22))
          + 0.22 * Math.abs(Math.sin(wall * 3.75 - i * 0.31));
      } else {
        target = 0.10 + 0.09 * Math.abs(Math.sin(wall * 0.75 + i * 0.25));
      }
      barHeights[i] = SMOOTHING * barHeights[i] + (1 - SMOOTHING) * Math.max(0.05, Math.min(1, target));
    }

    const now = performance.now();
    for (let i = 0; i < NUM_BARS; i++) {
      if (barHeights[i] > peakHeights[i]) {
        peakHeights[i] = barHeights[i];
        peakTimestamps[i] = now;
      } else if (now - peakTimestamps[i] > PEAK_HOLD_MS) {
        peakHeights[i] = Math.max(barHeights[i], peakHeights[i] - 0.025);
      }
    }
  }

  function lcdBackground(w, h) {
    ctx.fillStyle = "#02101c";
    ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = "rgba(126, 212, 240, 0.045)";
    for (let y = 0; y < h; y += 6) ctx.fillRect(0, y, w, 1);
    ctx.fillStyle = "rgba(126, 212, 240, 0.025)";
    for (let x = 0; x < w; x += 8) ctx.fillRect(x, 0, 1, h);
  }

  // Compose LCD-wide CSS filters (TINT hue-rotate + DIM brightness).
  // Both DIM and TINT call this so they cannot stomp each other.
  function applyLcdFilter() {
    if (!chassis) return;
    const lcd = chassis.querySelector(".pvfd-lcd");
    if (!lcd) return;
    const parts = [];
    const deg = TINT_HUE_DEG[tintIdx];
    if (deg !== 0) parts.push(`hue-rotate(${deg}deg)`);
    if (lcdDimmed) parts.push("brightness(0.55)");
    lcd.style.filter = parts.join(" ");
  }

  // Cyan-biased palette ramp: maps luma in [0,1] to (R,G,B) in [0,1].
  // Same shape as the verified Python pipeline. TINT's hue-rotate handles
  // amber/violet without needing a separate palette per tint.
  function cyanRamp(y) {
    const r = Math.max(0, Math.min(1, (y - 0.6) * 2.5));
    const g = Math.max(0, Math.min(1, y * 1.4 - 0.05));
    const b = Math.max(0, Math.min(1, 0.15 + y * 1.1));
    return [r, g, b];
  }

  function decodePackedClip(clip) {
    if (!clip || clip.bytes) return;
    try {
      const binary = atob(clip.data);
      const bytes = new Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
      clip.bytes = bytes;
    } catch (e) {
      console.warn("[PVFD] packed clip decode failed:", clip && clip.name, e);
      clip.bytes = new Uint8Array(0);
    }
  }

  function setActiveClip(idx) {
    if (!CLIPS.length) return;
    clipIdx = ((idx % CLIPS.length) + CLIPS.length) % CLIPS.length;
    clipStartMs = performance.now();
    decodePackedClip(CLIPS[clipIdx]);
    console.log(`[PVFD] clip mode: ${CLIPS[clipIdx].name}`);
  }

  function ensureClipRunning() {
    if (!CLIPS.length) return null;
    const clip = CLIPS[clipIdx] || CLIPS[0];
    if (!clipStartMs) clipStartMs = performance.now();
    decodePackedClip(clip);
    return clip;
  }

  function drawLCDStatus(text, w, h) {
    ctx.fillStyle = "rgba(2,16,28,0.72)";
    ctx.fillRect(Math.round(w * 0.24), Math.round(h * 0.42), Math.round(w * 0.52), 18);
    ctx.fillStyle = "rgba(168,228,244,0.88)";
    ctx.font = "bold 11px 'Share Tech Mono', monospace";
    ctx.textAlign = "center";
    ctx.fillText(text, Math.round(w * 0.50), Math.round(h * 0.42) + 13);
    ctx.textAlign = "left";
  }

  function drawClip(w, h, t, pulse) {
    lcdBackground(w, h);

    const clip = ensureClipRunning();
    if (!clip || !clip.bytes || !clip.bytes.length) {
      drawLCDStatus("CLIP DATA", w, h);
      return;
    }

    const frameCount = clip.frames || 1;
    const fps = clip.fps || 12;
    const elapsed = Math.max(0, (performance.now() - clipStartMs) / 1000);
    const frame = Math.floor(elapsed * fps) % frameCount;
    const frameOffset = frame * ((clip.w * clip.h) >> 1);

    const isRacingClip = String(clip.name || "").toUpperCase() === "RACING";
    const racingFitW = w * 0.78;
    const racingFitH = h * 0.76;
    const cellScale = isRacingClip ? Math.min(racingFitW / clip.w, racingFitH / clip.h) : 0;
    const cellW = isRacingClip ? cellScale : (w / clip.w);
    const cellH = isRacingClip ? cellScale : (h / clip.h);
    const clipDrawW = cellW * clip.w;
    const clipDrawH = cellH * clip.h;
    const offsetX = isRacingClip ? Math.round((w - clipDrawW) / 2) : 0;
    const offsetY = isRacingClip ? Math.round((h - clipDrawH) / 2) : 0;
    const gutterW = Math.max(1, Math.floor(cellW * 0.16));
    const gutterH = Math.max(1, Math.floor(cellH * 0.16));
    const drawW = Math.max(1, Math.floor(cellW - gutterW));
    const drawH = Math.max(1, Math.floor(cellH - gutterH));

    if (isRacingClip) {
      // Racing has tiny letters/logos and busy horizontal detail, so keep its
      // original pixel aspect instead of stretching it to the wider LCD shell.
      // The side gutters get a soft VFD rail treatment so the contained image
      // feels intentional, not like a random black box.
      const sideW = Math.max(0, offsetX);
      const railAlpha = 0.10 + Math.max(0, pulse) * 0.035;
      const scan = Math.round((t * 52) % Math.max(1, h));

      ctx.fillStyle = "rgba(1,12,22,0.62)";
      ctx.fillRect(0, 0, sideW, h);
      ctx.fillRect(w - sideW, 0, sideW, h);
      ctx.fillRect(offsetX, 0, Math.round(clipDrawW), Math.max(0, offsetY));
      ctx.fillRect(offsetX, offsetY + Math.round(clipDrawH), Math.round(clipDrawW), Math.max(0, h - offsetY - Math.round(clipDrawH)));

      ctx.fillStyle = `rgba(126,236,255,${railAlpha})`;
      for (let y = 5; y < h - 4; y += 8) {
        ctx.fillRect(Math.max(0, sideW - 13), y, 7, 2);
        ctx.fillRect(Math.min(w - sideW + 6, w - 7), y, 7, 2);
      }
      for (let x = offsetX + 10; x < offsetX + clipDrawW - 10; x += 18) {
        ctx.fillRect(x, Math.max(2, offsetY - 7), 8, 1);
        ctx.fillRect(x, Math.min(h - 3, offsetY + clipDrawH + 6), 8, 1);
      }

      const edgeGlow = 0.16 + Math.max(0, pulse) * 0.04;
      ctx.fillStyle = `rgba(120,232,255,${edgeGlow})`;
      ctx.fillRect(Math.max(0, offsetX - 3), Math.max(2, offsetY - 4), 1, Math.round(clipDrawH) + 8);
      ctx.fillRect(Math.min(w - 1, offsetX + Math.round(clipDrawW) + 2), Math.max(2, offsetY - 4), 1, Math.round(clipDrawH) + 8);
      ctx.fillRect(Math.max(0, offsetX - 2), Math.max(0, offsetY - 3), Math.round(clipDrawW) + 4, 1);
      ctx.fillRect(Math.max(0, offsetX - 2), Math.min(h - 1, offsetY + Math.round(clipDrawH) + 2), Math.round(clipDrawW) + 4, 1);

      ctx.fillStyle = "rgba(1,9,18,0.40)";
      ctx.fillRect(offsetX - 1, offsetY - 1, Math.round(clipDrawW) + 2, Math.round(clipDrawH) + 2);
      ctx.fillStyle = `rgba(216,248,255,${0.040 + Math.max(0, pulse) * 0.018})`;
      ctx.fillRect(offsetX, offsetY + Math.round((scan / h) * clipDrawH), Math.round(clipDrawW), 1);
    }

    for (let py = 0; py < clip.h; py++) {
      for (let px = 0; px < clip.w; px++) {
        const packed = clip.bytes[frameOffset + ((py * clip.w + px) >> 1)] || 0;
        const q = (px & 1) ? (packed & 15) : (packed >> 4);
        if (q <= 0) continue;
        const y = q / 15;
        const ramp = cyanRamp(y);
        const sparkle = ((px * 13 + py * 7 + frame) % 37 === 0) ? 0.08 : 0;
        const r = Math.min(255, Math.round((ramp[0] + sparkle) * 255));
        const g = Math.min(255, Math.round((ramp[1] + sparkle) * 255));
        const b = Math.min(255, Math.round((ramp[2] + sparkle) * 255));
        ctx.fillStyle = `rgb(${r},${g},${b})`;
        ctx.fillRect(Math.round(offsetX + px * cellW), Math.round(offsetY + py * cellH), drawW, drawH);
      }
    }

    // Very subtle scanline shimmer so the frame clips still feel like a VFD, not a GIF slapped on glass.
    ctx.fillStyle = `rgba(216,248,255,${0.035 + Math.max(0, pulse) * 0.018})`;
    const scanY = Math.round((t * 28) % Math.max(1, h));
    ctx.fillRect(isRacingClip ? offsetX : 0, scanY, isRacingClip ? Math.round(clipDrawW) : w, 1);
  }

  function drawDot(x, y, size, color, alpha = 1) {
    ctx.globalAlpha = alpha;
    ctx.fillStyle = color;
    ctx.fillRect(Math.round(x), Math.round(y), size, size);
    ctx.globalAlpha = 1;
  }

  function vfdHash(n) {
    return Math.abs(Math.sin(n * 127.1) * 43758.5453) % 1;
  }

  function drawFirework(cx, cy, radius, t, phase, color) {
    const cycle = (t * 0.32 + phase) % 1;
    const r = radius * (0.22 + cycle * 0.92);
    const fade = Math.max(0, 1 - cycle);
    const spokes = 14;
    for (let i = 0; i < spokes; i++) {
      const a = (Math.PI * 2 * i) / spokes + phase * 6.28;
      const x = cx + Math.cos(a) * r;
      const y = cy + Math.sin(a) * r * 0.72;
      drawDot(x, y, cycle < 0.72 ? 3 : 2, color, 0.18 + fade * 0.76);
      if (cycle > 0.20 && cycle < 0.86) {
        drawDot(cx + Math.cos(a) * r * 0.58, cy + Math.sin(a) * r * 0.42, 2, "#b8e896", fade * 0.42);
      }
    }
  }

  function drawGalaxyScene(w, h, t, pulse) {
    lcdBackground(w, h);

    // Stable pseudo-starfield, quantized to the LCD grid so it stays VFD/pixel instead of screensaver-slop.
    for (let i = 0; i < 72; i++) {
      const hx = vfdHash(i * 3.17);
      const hy = vfdHash(i * 9.41 + 2.3);
      const twinkle = 0.35 + 0.55 * Math.abs(Math.sin(t * (0.9 + hx) + i));
      const x = Math.round(hx * w / 4) * 4;
      const y = Math.round(hy * h / 4) * 4;
      drawDot(x, y, i % 9 === 0 ? 3 : 2, i % 5 === 0 ? "#b8e896" : "#7ed4f0", twinkle * 0.58);
    }

    const cx = w * 0.50 + Math.sin(t * 0.27) * w * 0.04;
    const cy = h * 0.53 + Math.cos(t * 0.22) * h * 0.04;
    const maxR = Math.min(w * 0.42, h * 0.78);
    const arms = 4;

    // Chunky spiral arms. The side fireworks make this feel like a head-unit animation, not a plain wallpaper.
    for (let arm = 0; arm < arms; arm++) {
      for (let j = 0; j < 74; j++) {
        const pct = j / 74;
        const a = pct * 6.1 + arm * (Math.PI * 2 / arms) + t * 0.55;
        const wobble = 1 + 0.13 * Math.sin(t * 1.7 + j * 0.31 + arm);
        const r = maxR * pct * wobble;
        const x = cx + Math.cos(a) * r;
        const y = cy + Math.sin(a) * r * 0.48;
        const alpha = 0.18 + pct * 0.62 + Math.max(0, pulse) * 0.10;
        const color = j % 11 === 0 ? "#d8f8ff" : (j % 3 === 0 ? "#a8e4f4" : "#4eb4d8");
        drawDot(x, y, pct > 0.64 ? 3 : 4, color, Math.min(0.92, alpha));
      }
    }

    // Bright pixel core and rotating scan ticks.
    ctx.fillStyle = "rgba(216,248,255,0.90)";
    ctx.fillRect(Math.round(cx - 8), Math.round(cy - 3), 16, 6);
    ctx.fillStyle = "rgba(184,232,150,0.78)";
    ctx.fillRect(Math.round(cx - 4), Math.round(cy - 8), 8, 16);
    for (let i = 0; i < 18; i++) {
      const a = i * 0.72 + t * 1.15;
      const r = maxR * (0.36 + 0.04 * Math.sin(t + i));
      drawDot(cx + Math.cos(a) * r, cy + Math.sin(a) * r * 0.45, 3, "#b8e896", 0.32 + 0.22 * Math.sin(t * 2 + i));
    }

    drawFirework(w * 0.12, h * 0.34, Math.min(54, h * 0.35), t, 0.10, "#a8e4f4");
    drawFirework(w * 0.86, h * 0.36, Math.min(62, h * 0.40), t, 0.43, "#d8f8ff");
    drawFirework(w * 0.82, h * 0.72, Math.min(44, h * 0.30), t, 0.74, "#4eb4d8");

  }

  function drawAurora(w, h, t, pulse) {
    lcdBackground(w, h);

    const cell = 4;
    const rows = Math.ceil(h / cell);
    const cols = Math.ceil(w / cell);
    for (let cx = 0; cx < cols; cx++) {
      const x = cx * cell;
      const base = h * (0.58 + 0.05 * Math.sin(t * 0.7));
      const y1 = base
        + Math.sin(x * 0.020 + t * 1.6) * h * 0.18
        + Math.sin(x * 0.047 - t * 0.9) * h * 0.09;
      const y2 = h * 0.72
        + Math.sin(x * 0.031 - t * 1.25) * h * 0.13
        + Math.sin(x * 0.013 + t * 0.8) * h * 0.05;

      for (let cy = 0; cy < rows; cy++) {
        const y = cy * cell;
        if (y > y1) {
          const fade = Math.min(1, (y - y1) / (h * 0.35));
          const shimmer = 0.70 + 0.30 * Math.sin(t * 5 + cx * 0.7 + cy * 0.35);
          const alpha = (0.22 + 0.52 * fade) * shimmer;
          drawDot(x, y, 3, cy % 3 === 0 ? "#a8e4f4" : "#4eb4d8", alpha);
        }
        if (y > y2 && (cx + cy) % 2 === 0) {
          drawDot(x, y, 3, "#7ed4f0", 0.20 + 0.15 * pulse);
        }
      }
    }

    // Bright, blocky wave crest like a 2000s head-unit demo.
    ctx.fillStyle = "rgba(168, 228, 244, 0.85)";
    for (let x = 0; x < w; x += 8) {
      const y = h * 0.50 + Math.sin(x * 0.028 + t * 1.8) * h * 0.13;
      ctx.fillRect(x, Math.round(y), 5, 3);
    }
  }

  function drawSpectrum(w, h, t) {
    lcdBackground(w, h);
    const GAP = 2;
    const sidePad = 7;
    const usableW = Math.max(80, w - sidePad * 2);
    const barStep = usableW / NUM_BARS;
    const barW = Math.max(3, barStep - GAP);
    const baseY = h - 10;
    const step = 5;

    // Background ghost wave so the analyzer never reads as a dead black screen.
    ctx.fillStyle = "rgba(20, 100, 150, 0.25)";
    for (let x = 0; x < w; x += 5) {
      const y = h * 0.58 + Math.sin(t * 1.8 + x * 0.025) * h * 0.16;
      ctx.fillRect(x, y, 3, baseY - y);
    }

    for (let i = 0; i < NUM_BARS; i++) {
      const bh = Math.max(12, barHeights[i] * h * 0.82);
      const ph = Math.max(12, peakHeights[i] * h * 0.82);
      const x = sidePad + i * barStep;
      const blocks = Math.floor(bh / step);
      for (let b = 0; b < blocks; b++) {
        const y = baseY - b * step;
        const color = b > blocks * 0.76 ? "#d8f8ff" : (b > blocks * 0.52 ? "#a8e4f4" : (b > blocks * 0.25 ? "#4eb4d8" : "#0b4a72"));
        ctx.fillStyle = color;
        ctx.globalAlpha = 0.62 + 0.32 * Math.sin(t * 5 + i * 0.25 + b * 0.4);
        ctx.fillRect(x, y, barW, 3);
        ctx.globalAlpha = 1;
      }
      ctx.fillStyle = "#b8e896";
      ctx.fillRect(x, baseY - ph - 3, barW, 2);
    }

  }

  const DOLPHIN_PIXELS = [
    "..................XX........",
    "...............XXXXXX.......",
    "............XXXXXXXXXXX.....",
    ".........XXXXXXXXXXXXXXX....",
    "......XXXXXXXXXXXXX..XXX....",
    "....XXXXXXXXXXXXXX.....XX...",
    "..XXXXXXXXXXXXXXX...XXXXX...",
    ".XXXXXXXXXXXXXXX.XXXXXX.....",
    "XXXXXXXXXXXXXX.XXXXX........",
    ".XXXXXXXXXXX..XXXX..........",
    "...XXXXXXX..XXX............",
    ".....XXX..XX...............",
    "......X....................",
  ];

  function drawPixelDolphin(x, y, cell) {
    for (let row = 0; row < DOLPHIN_PIXELS.length; row++) {
      const r = DOLPHIN_PIXELS[row];
      for (let col = 0; col < r.length; col++) {
        if (r[col] !== "X") continue;
        const px = x + col * cell;
        const py = y + row * cell;
        const shade = row < 4 ? "#d8f8ff" : (row < 8 ? "#a8e4f4" : "#4eb4d8");
        ctx.fillStyle = shade;
        ctx.fillRect(px, py, cell, cell);
      }
    }
    ctx.fillStyle = "#02101c";
    ctx.fillRect(x + 23 * cell, y + 5 * cell, cell, cell);
  }

  function drawDolphinScene(w, h, t, pulse) {
    drawAurora(w, h, t * 0.75, pulse * 0.25);
    ctx.fillStyle = "rgba(2,10,20,0.18)";
    ctx.fillRect(0, 0, w, h);

    const cell = Math.max(2, Math.min(4, Math.floor(h / 42)));
    const spriteW = DOLPHIN_PIXELS[0].length * cell;
    const spriteH = DOLPHIN_PIXELS.length * cell;
    dolphinX += Math.max(1.0, w / 420);
    if (dolphinX > w + spriteW) dolphinX = -spriteW - 12;

    const dy = Math.max(28, Math.min(h - spriteH - 14, h * 0.44 + Math.sin(t * 1.7) * h * 0.10));

    // Small pixel wake before the dolphin; this fixes the "warped blob" read.
    ctx.fillStyle = "rgba(168,228,244,0.75)";
    for (let i = 0; i < 7; i++) {
      const wx = dolphinX - i * 9;
      const wy = dy + spriteH * 0.55 + Math.sin(t * 5 + i) * 5;
      ctx.fillRect(wx, wy, 5, 2);
    }
    drawPixelDolphin(Math.round(dolphinX), Math.round(dy), cell);

    if (Math.random() < 0.22) {
      dolphinBubbles.push({
        x: dolphinX - 10 + Math.random() * 8,
        y: dy + spriteH * 0.55 + Math.random() * 10,
        r: 2, life: 0,
      });
    }
    for (let i = dolphinBubbles.length - 1; i >= 0; i--) {
      const b = dolphinBubbles[i];
      b.life += 1; b.y -= 0.55;
      b.x += Math.sin(b.life * 0.14) * 0.4;
      if (b.life > 70 || b.y < 0) { dolphinBubbles.splice(i, 1); continue; }
      ctx.fillStyle = `rgba(168, 228, 244, ${0.85 - b.life / 82})`;
      ctx.fillRect(Math.round(b.x), Math.round(b.y), b.r, b.r);
    }
  }

  function drawDemo(w, h, t, pulse) {
    lcdBackground(w, h);
    demoSweep += 0.65;
    const cell = 6;
    const cols = Math.ceil(w / cell);
    const rows = Math.ceil(h / cell);
    const meterX = w - 54;

    // Period-correct block field with a clean scan bar. Keep it vivid, but do not let
    // decorative lines stop halfway across the screen and look broken.
    for (let cy = 0; cy < rows; cy++) {
      for (let cx = 0; cx < cols; cx++) {
        const x = cx * cell;
        const y = cy * cell;
        const oval = Math.sin(cx * 0.34 + t * 1.7) * 0.9 + Math.cos(cy * 0.58 - t * 1.2);
        const diagonal = Math.sin((cx + cy) * 0.22 - t * 1.8);
        const sweep = Math.abs(((x + demoSweep * 3) % (w + 80)) - w * 0.5);
        if (x < meterX - 10 && (oval > 0.95 || diagonal > 0.97 || sweep < 24)) {
          const alpha = sweep < 24 ? 0.84 : (oval > 0.95 ? 0.42 : 0.26);
          const color = sweep < 24 ? "#d8f8ff" : ((cx + cy) % 3 === 0 ? "#a8e4f4" : "#4eb4d8");
          drawDot(x, y, 4, color, alpha);
        }
      }
    }

    // Clean full-width dotted ribbon near the lower third. This replaces the old broken
    // half-width squiggle that looked like it got cut off.
    for (let x = 12; x < meterX - 12; x += 8) {
      const y1 = h * 0.73 + Math.sin(t * 2.6 + x * 0.038) * 5;
      const y2 = y1 + 10;
      drawDot(x, y1, 4, "#a8e4f4", 0.72);
      if ((x / 8 + Math.floor(t * 10)) % 2 === 0) drawDot(x, y2, 4, "#4eb4d8", 0.45);
    }

    // Big period-correct equalizer blocks on the right edge like the Pioneer reference.
    const meterW = 7;
    for (let i = 0; i < 5; i++) {
      const lvl = 5 + Math.floor(10 * Math.abs(Math.sin(t * (1.5 + i * 0.2) + i)));
      for (let b = 0; b < lvl; b++) {
        ctx.fillStyle = b > 10 ? "#d8f8ff" : (b > 6 ? "#a8e4f4" : "#4eb4d8");
        ctx.fillRect(meterX + i * (meterW + 3), h - 12 - b * 5, meterW, 3);
      }
    }

    // Demo label sits high enough to be readable and clear of the dotted ribbon.
    ctx.fillStyle = "rgba(184,232,150,0.85)";
    ctx.font = "bold 16px 'Share Tech Mono', monospace";
    ctx.fillText("PIONEER DEMO", 12, Math.max(54, h * 0.46));
  }

  function syncCurrentTrackFromPlayer() {
    const item = Spicetify.Player.data && Spicetify.Player.data.item;
    if (!item) return;

    const uri = item.uri || item.link || item.name || "";
    if (uri && uri !== lastTrackUri) {
      lastTrackUri = uri;
      trackTitle = (item.name || "").toUpperCase();
      trackArtist = ((item.artists && item.artists.map(a => a.name).join(", ")) || "").toUpperCase();
      loadAnalysis(item.uri);
    }

    if (!trackTitle && item.name) {
      trackTitle = item.name.toUpperCase();
    }
    if (!trackArtist && item.artists) {
      trackArtist = item.artists.map(a => a.name).join(", ").toUpperCase();
    }
  }

  function updateOverlays(tSec) {
    const titleEl  = chassis.querySelector(".pvfd-lcd-track");
    const artistEl = chassis.querySelector(".pvfd-lcd-artist");
    const timeEl   = chassis.querySelector(".pvfd-lcd-time");
    if (titleEl)  titleEl.textContent  = "▶ " + (trackTitle  || "—");
    if (artistEl) artistEl.textContent = trackArtist || "";
    if (timeEl)   timeEl.textContent   = fmtTime(tSec * 1000);
  }

  function updateLknobLED() {
    const arc = chassis.querySelector(".pvfd-knob-led-arc");
    const ind = chassis.querySelector(".pvfd-knob-indicator");
    if (!arc) return;
    const v = Spicetify.Player.getVolume();
    const sweepDeg = 270 * v;
    arc.style.setProperty("--pvfd-led-deg", sweepDeg + "deg");
    if (ind) ind.style.setProperty("--pvfd-rot", (-135 + 270 * v) + "deg");
  }

  function updateNavLED(tSec) {
    const ring = chassis.querySelector(".pvfd-nav-led-ring");
    if (!ring) return;
    const p = beatPulse(tSec);
    ring.style.boxShadow = `0 0 ${14 + p * 18}px rgba(78, 180, 216, ${0.95 - p * 0.1}),
      inset 0 0 ${10 + p * 10}px rgba(140, 220, 250, ${0.6 + p * 0.3})`;
  }

  let lastFrame = 0;
  let lastModeName = "";
  function loop(ts) {
    requestAnimationFrame(loop);
    if (ts - lastFrame < FRAME_INTERVAL_MS) return;
    lastFrame = ts;
    if (!ctx || !chassis) return;

    if (modeForcedIdx >= 0) {
      modeIdx = modeForcedIdx;
    } else if (ts - modeLastSwitchMs > MODE_CYCLE_MS) {
      modeIdx = (modeIdx + 1) % MODES.length;
      modeLastSwitchMs = ts;
    }
    const modeName = MODES[modeIdx];
    if (modeName !== lastModeName) {
      if (modeName === "CLIP") setActiveClip(clipIdx);
      lastModeName = modeName;
    }
    if (chassis) chassis.setAttribute("data-pvfd-mode", modeName.toLowerCase());

    syncCurrentTrackFromPlayer();
    updateBars();

    const w = canvas.clientWidth, h = canvas.clientHeight;
    const tSec = (Spicetify.Player.getProgress() || 0) / 1000;
    const tWall = ts / 1000;
    const pulse = beatPulse(tSec) + SINE_BASE * Math.sin(tWall * 2);

    if (modeName === "GALAXY")        drawGalaxyScene(w, h, tWall, pulse);
    else if (modeName === "SPECTRUM") drawSpectrum(w, h, tWall);
    else if (modeName === "DOLPHIN")  drawDolphinScene(w, h, tWall, pulse);
    else if (modeName === "DEMO")     drawDemo(w, h, tWall, pulse);
    else if (modeName === "CLIP")     drawClip(w, h, tWall, pulse);

    updateOverlays(tSec);
    updateLknobLED();
    updateNavLED(tSec);
  }

  function onTrackChange() {
    syncCurrentTrackFromPlayer();
    const playBtn = chassis && chassis.querySelector("[data-pvfd='play']");
    if (playBtn) playBtn.textContent = Spicetify.Player.isPlaying() ? "⏸" : "▶";
  }

  function attach() {
    if (!injectChassis()) {
      setTimeout(attach, 500);
      return;
    }
    onTrackChange();
    Spicetify.Player.addEventListener("songchange", onTrackChange);
    Spicetify.Player.addEventListener("onplaypause", () => {
      const playBtn = chassis && chassis.querySelector("[data-pvfd='play']");
      if (playBtn) playBtn.textContent = Spicetify.Player.isPlaying() ? "⏸" : "▶";
    });
    requestAnimationFrame(loop);

    const obs = new MutationObserver(() => {
      const bar = findPlayerBar();
      if (bar && !bar.querySelector(".pvfd-chassis")) injectChassis();
    });
    obs.observe(document.body, { childList: true, subtree: true });

    console.log("[PVFD] v0.3.2 online — ART removed; RACING tighter-contained; packed LCD clips active.");
  }

  attach();
})();
